# ---------------------------------------------------------------------------
# BLAKE3 (unkeyed, 32-byte output). This is a small original implementation
# sufficient for content-addressing cards without external dependencies.
# ---------------------------------------------------------------------------
IV = [
    0x6A09E667, 0xBB67AE85, 0x3C6EF372, 0xA54FF53A,
    0x510E527F, 0x9B05688C, 0x1F83D9AB, 0x5BE0CD19,
]
MSG_PERM = [2, 6, 3, 10, 7, 0, 4, 13, 1, 11, 12, 5, 9, 14, 15, 8]
MASK32 = 0xFFFFFFFF
CHUNK_LEN = 1024
BLOCK_LEN = 64
CHUNK_START = 1
CHUNK_END = 2
PARENT = 4
ROOT = 8


def _rotr32(x, n):
    return ((x >> n) | ((x << (32 - n)) & MASK32)) & MASK32


def _g(state, a, b, c, d, mx, my):
    state[a] = (state[a] + state[b] + mx) & MASK32
    state[d] = _rotr32(state[d] ^ state[a], 16)
    state[c] = (state[c] + state[d]) & MASK32
    state[b] = _rotr32(state[b] ^ state[c], 12)
    state[a] = (state[a] + state[b] + my) & MASK32
    state[d] = _rotr32(state[d] ^ state[a], 8)
    state[c] = (state[c] + state[d]) & MASK32
    state[b] = _rotr32(state[b] ^ state[c], 7)


def _compress(cv, block_words, counter, block_len, flags):
    state = cv[:] + IV[:4] + [counter & MASK32, (counter >> 32) & MASK32, block_len, flags]
    m = block_words[:]
    for _ in range(7):
        _g(state, 0, 4, 8, 12, m[0], m[1])
        _g(state, 1, 5, 9, 13, m[2], m[3])
        _g(state, 2, 6, 10, 14, m[4], m[5])
        _g(state, 3, 7, 11, 15, m[6], m[7])
        _g(state, 0, 5, 10, 15, m[8], m[9])
        _g(state, 1, 6, 11, 12, m[10], m[11])
        _g(state, 2, 7, 8, 13, m[12], m[13])
        _g(state, 3, 4, 9, 14, m[14], m[15])
        m = [m[i] for i in MSG_PERM]
    out = [0] * 16
    for i in range(8):
        out[i] = state[i] ^ state[i + 8]
        out[i + 8] = state[i + 8] ^ cv[i]
    return out


def _block_words(block):
    return list(struct.unpack('<16I', block + b'\0' * (64 - len(block))))


def _words_to_bytes(words):
    return b''.join(struct.pack('<I', w & MASK32) for w in words)


def _chunk_output(data, chunk_counter):
    cv = IV[:]
    off = 0
    first = True
    # Compress all but the last block as chaining-value blocks.
    while len(data) - off > BLOCK_LEN:
        flags = CHUNK_START if first else 0
        cv = _compress(cv, _block_words(data[off:off + BLOCK_LEN]), chunk_counter, BLOCK_LEN, flags)[:8]
        off += BLOCK_LEN
        first = False
    flags = (CHUNK_START if first else 0) | CHUNK_END
    block = data[off:]
    return (cv, _block_words(block), chunk_counter, len(block), flags)


def _output_bytes(output, root=False):
    cv, block_words, counter, block_len, flags = output
    if root:
        flags |= ROOT
    words = _compress(cv, block_words, counter, block_len, flags)
    return _words_to_bytes(words)


def _output_cv(output):
    cv, block_words, counter, block_len, flags = output
    return _compress(cv, block_words, counter, block_len, flags)[:8]


def _parent_output(left_cv, right_cv):
    block = _words_to_bytes(left_cv + right_cv)
    return (IV[:], _block_words(block), 0, BLOCK_LEN, PARENT)


def _parent_cv(left_cv, right_cv):
    return _output_cv(_parent_output(left_cv, right_cv))


def blake3_hex(data: bytes) -> str:
    if len(data) <= CHUNK_LEN:
        return _output_bytes(_chunk_output(data, 0), root=True)[:32].hex()
    cvs = []
    num_chunks = (len(data) + CHUNK_LEN - 1) // CHUNK_LEN
    for idx in range(num_chunks):
        chunk = data[idx * CHUNK_LEN:(idx + 1) * CHUNK_LEN]
        cv = _output_cv(_chunk_output(chunk, idx))
        total = idx + 1
        while total & 1 == 0:
            left = cvs.pop()
            cv = _parent_cv(left, cv)
            total >>= 1
        cvs.append(cv)
    cv = cvs.pop()
    while cvs:
        left = cvs.pop()
        # The last merge is emitted as the root output.
        if not cvs:
            return _output_bytes(_parent_output(left, cv), root=True)[:32].hex()
        cv = _parent_cv(left, cv)
    return _words_to_bytes(cv)[:32].hex()


# ---------------------------------------------------------------------------
# Card model / parser
# ---------------------------------------------------------------------------
class ParseError(Exception):
    def __init__(self, message, path, line):
        super().__init__(message)
        self.message = message
        self.path = str(path)
        self.line = line


class Card:
    def __init__(self, hash_, family_hash, deck_name, file_path, line_start, line_end, kind, data):
        self.hash = hash_
        self.family_hash = family_hash
        self.deck_name = deck_name
        self.file_path = str(file_path)
        self.line_start = int(line_start)
        self.line_end = int(line_end)
        self.kind = kind
        self.data = data

    def to_json_obj(self, performance):
        obj = {
            "hash": self.hash,
            "familyHash": self.family_hash,
            "deckName": self.deck_name,
            "location": {
                "filePath": self.file_path,
                "lineStart": self.line_start,
                "lineEnd": self.line_end,
            },
            "content": {},
            "performance": performance,
        }
        if self.kind == "basic":
            obj["content"]["basic"] = {
                "question": self.data["question"],
                "answer": self.data["answer"],
            }
        else:
            obj["content"]["cloze"] = {
                "text": self.data["text"],
                "start": self.data["start"],
                "end": self.data["end"],
            }
        return obj


def hash_basic(question, answer):
    return blake3_hex(("Basic" + question + answer).encode('utf-8'))


def hash_cloze_family(text):
    return blake3_hex(("Cloze" + text).encode('utf-8'))


def hash_cloze(text, start, end):
    end_u = end & 0xFFFFFFFFFFFFFFFF
    return blake3_hex(("Cloze" + text).encode('utf-8') + struct.pack('<Q', start) + struct.pack('<Q', end_u))


def normalize_block(lines):
    return "\n".join(lines).strip()


def is_q(line): return line.startswith("Q:")
def is_a(line): return line.startswith("A:")
def is_c(line): return line.startswith("C:")


def parse_cloze_deletions(raw):
    out = []
    spans = []
    in_cloze = False
    start = 0
    byte_pos = 0
    i = 0
    while i < len(raw):
        ch = raw[i]
        # Backslash escapes square brackets for cloze parsing, and the
        # backslash itself is removed, as observed in the web/export text.
        if ch == '\\' and i + 1 < len(raw) and raw[i + 1] in '[]':
            lit = raw[i + 1]
            out.append(lit)
            byte_pos += len(lit.encode('utf-8'))
            i += 2
            continue
        if ch == '[':
            in_cloze = True
            start = byte_pos
            i += 1
            continue
        if ch == ']':
            if in_cloze:
                end = byte_pos - 1
                if end < 0:
                    end = 0xFFFFFFFFFFFFFFFF
                spans.append((start, end))
                in_cloze = False
            i += 1
            continue
        out.append(ch)
        byte_pos += len(ch.encode('utf-8'))
        i += 1
    return "".join(out), spans


def parse_file(path: Path):
