# ---------------------------------------------------------------------------
# FSRS-like scheduling (matches observed first-review values)
# ---------------------------------------------------------------------------
STABILITY0 = {
    'Forgot': 0.40255,
    'Hard': 1.18385,
    'Good': 3.173,
    'Easy': 15.69105,
}
GRADE_NUM = {'Forgot': 1, 'Hard': 2, 'Good': 3, 'Easy': 4}
W4 = 7.1949
W5 = 0.5345


def schedule_review(conn, h, grade, reviewed_at_dt):
    prev = conn.execute('SELECT * FROM cards WHERE hash=?', (h,)).fetchone()
    g = GRADE_NUM[grade]
    if prev is None:
        stability = STABILITY0[grade]
        difficulty = W4 - math.exp((g - 1) * W5) + 1
        review_count = 1
    else:
        # A compact approximation for later reviews: keep behavior stable and
        # monotonic without depending on external FSRS libraries.
        old_s = float(prev['stability'])
        old_d = float(prev['difficulty'])
        if grade == 'Forgot':
            stability = max(0.1, old_s * 0.45)
            difficulty = min(10.0, old_d + 1.2)
        elif grade == 'Hard':
            stability = max(1.0, old_s * 1.2)
            difficulty = min(10.0, old_d + 0.4)
        elif grade == 'Good':
            stability = old_s * 2.5
            difficulty = max(1.0, old_d - 0.15)
        else:
            stability = old_s * 3.8
            difficulty = max(1.0, old_d - 0.6)
        review_count = int(prev['review_count']) + 1
    # The original computes an interval formula that is mathematically the
    # stability at 90% retention, yielding the following floating artifacts.
    interval_raw = stability * 0.9999999999999998
    interval_days = int(round(interval_raw))
    if interval_days < 1:
        interval_days = 1
    due = (reviewed_at_dt.date() + timedelta(days=interval_days)).isoformat()
    reviewed_at = fmt_ts(reviewed_at_dt)
    conn.execute('''INSERT INTO cards(hash,last_reviewed_at,stability,difficulty,interval_raw,interval_days,due_date,review_count)
                    VALUES(?,?,?,?,?,?,?,?)
                    ON CONFLICT(hash) DO UPDATE SET
                      last_reviewed_at=excluded.last_reviewed_at,
                      stability=excluded.stability,
                      difficulty=excluded.difficulty,
                      interval_raw=excluded.interval_raw,
                      interval_days=excluded.interval_days,
                      due_date=excluded.due_date,
                      review_count=excluded.review_count''',
                 (h, reviewed_at, stability, difficulty, interval_raw, interval_days, due, review_count))
    return {
        'hash': h,
        'reviewed_at': reviewed_at,
        'grade': grade,
        'stability': stability,
        'difficulty': difficulty,
        'interval_raw': interval_raw,
        'interval_days': interval_days,
        'due_date': due,
    }


def fmt_ts(dt=None):
    if dt is None:
        dt = datetime.now()
    return dt.strftime('%Y-%m-%dT%H:%M:%S.%f')[:-3]


def parse_ts(ts):
    try:
        return datetime.strptime(ts, '%Y-%m-%dT%H:%M:%S.%f')
    except Exception:
        return datetime.now()


