    root = ensure_collection_path(root)
    conn = connect_db(root)
    obj = export_obj(root, conn)
    conn.close()
    s = json.dumps(obj, ensure_ascii=False, indent=2)
    if output:
        try:
            Path(output).write_text(s, encoding='utf-8')
        except OSError as e:
            print('hashcards: error: I/O error: Os {', file=sys.stderr)
            print(f'    code: {e.errno},', file=sys.stderr)
            # Python names differ slightly from Rust; use common display.
            kind = 'NotFound' if e.errno == 2 else e.__class__.__name__
            print(f'    kind: {kind},', file=sys.stderr)
            print(f'    message: "{e.strerror}",', file=sys.stderr)
            print('}', file=sys.stderr)
            sys.exit(1)
