class DrillState:
    def __init__(self, root, conn, cards, answer_controls):
        self.root = root
        self.conn = conn
        self.cards = cards
        self.answer_controls = answer_controls
        self.index = 0
        self.completed = 0
        self.revealed = False
        self.finished = False
        self.shutdown = False
        self.started_dt = datetime.now()
        self.ended_dt = None
        self.reviews = []
        self.history = []
        self.session_saved = False

    def current(self):
        if self.index < len(self.cards):
            return self.cards[self.index]
        return None

    def save_session(self):
        if self.session_saved:
            return
        self.ended_dt = datetime.now()
        cur = self.conn.cursor()
        cur.execute('INSERT INTO sessions(started_at, ended_at) VALUES(?,?)', (fmt_ts(self.started_dt), fmt_ts(self.ended_dt)))
        sid = cur.lastrowid
        for r in self.reviews:
            cur.execute('''INSERT INTO reviews(session_id, hash, reviewed_at, grade, stability, difficulty, interval_raw, interval_days, due_date)
                           VALUES(?,?,?,?,?,?,?,?,?)''',
                        (sid, r['hash'], r['reviewed_at'], r['grade'], r['stability'], r['difficulty'], r['interval_raw'], r['interval_days'], r['due_date']))
        self.conn.commit()
        self.session_saved = True

    def grade(self, grade):
        card = self.current()
        if not card:
            return
        now = datetime.now()
        # Compute schedule in a transaction, but session/review rows are added
        # only when the session is saved. Card performance is committed then by
        # using the same connection; if the process is killed before save, the
        # original also discards partial sessions in common paths. To emulate
        # that, we defer by recording enough info and applying on save manually.
        prev = self.conn.execute('SELECT * FROM cards WHERE hash=?', (card.hash,)).fetchone()
        g = GRADE_NUM[grade]
        if prev is None:
            stability = STABILITY0[grade]
            difficulty = W4 - math.exp((g - 1) * W5) + 1
            review_count = 1
        else:
            old_s = float(prev['stability']); old_d = float(prev['difficulty'])
            if grade == 'Forgot': stability, difficulty = max(0.1, old_s * 0.45), min(10.0, old_d + 1.2)
            elif grade == 'Hard': stability, difficulty = max(1.0, old_s * 1.2), min(10.0, old_d + 0.4)
            elif grade == 'Good': stability, difficulty = old_s * 2.5, max(1.0, old_d - 0.15)
            else: stability, difficulty = old_s * 3.8, max(1.0, old_d - 0.6)
            review_count = int(prev['review_count']) + 1
        interval_raw = stability * 0.9999999999999998
        interval_days = max(1, int(round(interval_raw)))
        due = (now.date() + timedelta(days=interval_days)).isoformat()
        r = {'hash': card.hash, 'reviewed_at': fmt_ts(now), 'grade': grade, 'stability': stability, 'difficulty': difficulty,
             'interval_raw': interval_raw, 'interval_days': interval_days, 'due_date': due, 'review_count': review_count}
        self.reviews.append(r)
        self.history.append((self.index, self.completed, self.revealed))
        self.revealed = False
        if grade in ('Good', 'Easy'):
            self.completed += 1
            self.index += 1
            if self.index >= len(self.cards):
                self.finished = True
                self.apply_card_updates()
                self.save_session()
        # Forgot/Hard leave the card in place.

    def apply_card_updates(self):
        # Apply the latest review for each card hash in order.
        for r in self.reviews:
            self.conn.execute('''INSERT INTO cards(hash,last_reviewed_at,stability,difficulty,interval_raw,interval_days,due_date,review_count)
                                 VALUES(?,?,?,?,?,?,?,?)
                                 ON CONFLICT(hash) DO UPDATE SET
                                   last_reviewed_at=excluded.last_reviewed_at,
                                   stability=excluded.stability,
                                   difficulty=excluded.difficulty,
                                   interval_raw=excluded.interval_raw,
                                   interval_days=excluded.interval_days,
                                   due_date=excluded.due_date,
                                   review_count=excluded.review_count''',
                              (r['hash'], r['reviewed_at'], r['stability'], r['difficulty'], r['interval_raw'], r['interval_days'], r['due_date'], r['review_count']))
        self.conn.commit()

    def end(self):
        self.finished = True
        self.apply_card_updates()
        self.save_session()

    def undo(self):
        if not self.history:
            return
        self.index, self.completed, self.revealed = self.history.pop()
        if self.reviews:
            self.reviews.pop()
        self.finished = False


def render_drill_page(state, host, port):
    base_url = f'http://localhost:{port}'
    if state.finished:
        ended = state.ended_dt or datetime.now()
        dur = int((ended - state.started_dt).total_seconds())
        reviewed = len(state.reviews)
        pace = (dur / reviewed) if reviewed else 0.0
        body = html_page_head()
        body += '<div class="finished"><h1>Session Completed 🎉</h1>'
        body += f'<div class="summary">Reviewed {reviewed} cards in {dur} seconds.</div><h2>Session Stats</h2><div class="stats"><table><tbody>'
        rows = [
            ('Total Cards', str(len(state.cards))),
            ('Cards Reviewed', str(reviewed)),
            ('Started', state.started_dt.strftime('%Y-%m-%d %H:%M:%S')),
            ('Finished', ended.strftime('%Y-%m-%d %H:%M:%S')),
            ('Duration (seconds)', str(dur)),
            ('Pace (s/card)', f'{pace:.2f}'),
        ]
        for k, v in rows:
            body += f'<tr><td class="key">{k}</td><td class="val">{v}</td></tr>'
        body += '</tbody></table></div><div class="shutdown-container"><form action="/" method="post"><input class="shutdown-button" id="shutdown" type="submit" name="action" value="Shutdown" title="Shut down the server"></form></div></div><script src="/script.js"></script></body></html>'
        return body
    card = state.current()
    pct = int((state.completed / len(state.cards)) * 100) if state.cards else 100
    body = html_page_head()
    body += f'<div class="root"><div class="header"><div class="progress-bar"><div class="progress-fill" style="width: {pct}%;"></div></div></div>'
    body += '<div class="card-container"><div class="card"><div class="card-header"><h1>' + html.escape(card.deck_name) + '</h1></div><div class="card-content">'
    if card.kind == 'basic':
        q = render_markdown(card.data['question'], base_url)
        a = render_markdown(card.data['answer'], base_url) if state.revealed else ''
        body += '<div class="question rich-text">' + q + '</div><div class="answer rich-text">' + a + '</div>'
    else:
        prompt = render_cloze_prompt(card.data['text'], card.data['start'], card.data['end'], state.revealed, base_url)
        body += '<div class="prompt rich-text">' + prompt + '</div>'
    body += '</div></div></div>'
    body += render_controls(state.revealed, bool(state.history), state.answer_controls)
    body += '</div><script src="/script.js"></script></body></html>'
    return body


def select_drill_cards(root, conn, card_limit=None, new_card_limit=None, from_deck=None, bury_siblings=True):
    cards = parse_collection(root)
    today = date.today().isoformat()
    selected = []
    new_count = 0
    for c in cards:
        if from_deck and c.deck_name != from_deck:
            continue
        perf = perf_for_hash(conn, c.hash)
        if perf is None:
            if new_card_limit is not None and new_count >= new_card_limit:
                continue
            selected.append(c)
            new_count += 1
        else:
            if perf['dueDate'] <= today:
                selected.append(c)
    selected.sort(key=lambda c: c.hash)
    if card_limit is not None:
        selected = selected[:card_limit]
    if bury_siblings:
        out = []
        families = set()
        for c in selected:
            if c.family_hash is not None:
                if c.family_hash in families:
                    continue
                families.add(c.family_hash)
            out.append(c)
        selected = out
    return selected


def run_server(root, conn, cards, host, port, answer_controls):
    state = DrillState(root, conn, cards, answer_controls)

    class Handler(BaseHTTPRequestHandler):
        server_version = 'hashcards'
        sys_version = ''

        def log_message(self, format, *args):
            return

        def send_body(self, code, body, ctype='text/html; charset=utf-8', headers=None):
            data = body.encode('utf-8') if isinstance(body, str) else body
            self.send_response(code)
            self.send_header('content-type', ctype)
            self.send_header('content-length', str(len(data)))
            if headers:
                for k, v in headers.items():
                    self.send_header(k, v)
            self.end_headers()
            self.wfile.write(data)

        def do_GET(self):
            path = urllib.parse.urlparse(self.path).path
            if path == '/':
                self.send_body(200, render_drill_page(state, host, port))
            elif path == '/style.css':
                self.send_body(200, STYLE_CSS, 'text/css', {'cache-control': 'public, max-age=604800, immutable'})
            elif path == '/script.js':
                self.send_body(200, script_js(root), 'text/javascript')
            elif path.startswith('/katex/'):
                # Placeholder local KaTeX assets. The UI also uses CDN highlight.js.
                if path.endswith('.css'):
                    self.send_body(200, '/* katex placeholder */\n', 'text/css', {'cache-control': 'public, max-age=604800, immutable'})
                else:
                    self.send_body(200, '/* katex placeholder */\n', 'text/javascript', {'cache-control': 'public, max-age=604800, immutable'})
            elif path.startswith('/file/'):
                rel = urllib.parse.unquote(path[len('/file/'):])
                fp = (root / rel).resolve()
                try:
                    fp.relative_to(root.resolve())
                    data = fp.read_bytes()
                    ctype = mimetypes.guess_type(str(fp))[0] or 'application/octet-stream'
                    self.send_body(200, data, ctype)
                except Exception:
                    self.send_body(404, 'Not Found')
            else:
                self.send_body(404, 'Not Found')

        def do_HEAD(self):
            path = urllib.parse.urlparse(self.path).path
            if path == '/':
                body = render_drill_page(state, host, port).encode('utf-8')
                self.send_response(200)
                self.send_header('content-type', 'text/html; charset=utf-8')
                self.send_header('content-length', str(len(body)))
                self.end_headers()
            else:
                self.send_response(404); self.send_header('content-type', 'text/html; charset=utf-8'); self.send_header('content-length', '9'); self.end_headers()

        def do_POST(self):
            length = int(self.headers.get('content-length', '0') or '0')
            body = self.rfile.read(length).decode('utf-8', errors='replace')
            params = urllib.parse.parse_qs(body)
            action = params.get('action', [''])[0]
            if action == 'Reveal':
                state.revealed = True
            elif action in ('Forgot', 'Hard', 'Good', 'Easy'):
                if state.revealed:
                    state.grade(action)
            elif action == 'Undo':
                state.undo()
            elif action == 'End':
                state.end()
            elif action == 'Shutdown':
                state.shutdown = True
                # Save empty completed session if not already saved.
                if not state.session_saved:
                    state.end()
                self.send_response(303)
                self.send_header('location', '/')
                self.send_header('content-length', '0')
                self.end_headers()
                # Shutdown asynchronously after response.
                import threading
                threading.Thread(target=self.server.shutdown, daemon=True).start()
                return
            self.send_response(303)
            self.send_header('location', '/')
            self.send_header('content-length', '0')
            self.end_headers()

    httpd = ThreadingHTTPServer((host, port), Handler)
    try:
        httpd.serve_forever()
    finally:
        conn.close()


def cmd_drill(root, opts):
    root = ensure_collection_path(root)
    conn = connect_db(root)
    cards = select_drill_cards(root, conn, opts.get('card_limit'), opts.get('new_card_limit'), opts.get('from_deck'), opts.get('bury_siblings', True))
    if not cards:
        print('No cards due today.')
        conn.close()
        return
    run_server(root, conn, cards, opts.get('host', '127.0.0.1'), opts.get('port', 8000), opts.get('answer_controls', 'full'))


