def die_clap(msg, usage=None, tip=None):
    print(msg, file=sys.stderr)
    if tip:
        print('', file=sys.stderr); print(tip, file=sys.stderr)
    if usage:
        print('', file=sys.stderr); print(usage, file=sys.stderr)
    print('', file=sys.stderr); print("For more information, try '--help'.", file=sys.stderr)
    sys.exit(2)


def parse_dir(args):
    if not args:
        return Path('.')
    if len(args) == 1:
        return Path(args[0])
    die_clap(f"error: unexpected argument '{args[1]}' found")


def parse_int_value(opt, val):
    try:
        n = int(val)
        if n < 0:
            raise ValueError
        return n
    except Exception:
        die_clap(f"error: invalid value '{val}' for '{opt} <{opt[2:].replace('-', '_').upper()}>'")


def parse_bool_option(name, val):
    if val == 'true': return True
    if val == 'false': return False
    die_clap(f"error: invalid value '{val}' for '{name} <{name[2:].replace('-', '_').upper()}>'\n  [possible values: true, false]")


def handle_parse_error(e):
    print(f"hashcards: error: Parse error: {e.message}. Location: {e.path}:{e.line}", file=sys.stderr)
    sys.exit(1)


def main(argv):
    if not argv or argv[0] in ('-h', '--help'):
        print(MAIN_HELP)
        return
    if argv[0] in ('-V', '--version'):
