            if len(rest) >= 2 and rest[1] == 'list': print(ORPHANS_LIST_HELP); return
            if len(rest) >= 2 and rest[1] == 'delete': print(ORPHANS_DELETE_HELP); return
            print(ORPHANS_HELP); return
        die_clap(f"error: unrecognized subcommand '{rest[0]}'", "Usage: executable <COMMAND>")
    cmd = argv[0]
    args = argv[1:]
    try:
        if cmd == 'check':
            if args and args[0] in ('-h', '--help'):
                print(CHECK_HELP); return
            cmd_check(parse_dir(args))
        elif cmd == 'stats':
            if args and args[0] == '--help': print(STATS_HELP_LONG); return
            if args and args[0] == '-h': print(STATS_HELP_SHORT); return
            fmt = 'html'; rest = []
            i = 0
