                    opts['answer_controls'] = val; i += 1; continue
                if a.startswith('--'):
                    die_clap(f"error: unexpected argument '{a}' found", "Usage: executable drill [OPTIONS] [DIRECTORY]")
                rest.append(a); i += 1
            cmd_drill(parse_dir(rest), opts)
        else:
            die_clap(f"error: unrecognized subcommand '{cmd}'", "Usage: executable <COMMAND>")
    except ParseError as e:
