#!/usr/bin/env python3
import os
import sys
import json
import math
import html
import sqlite3
import random
import mimetypes
import urllib.parse
import struct
from pathlib import Path
from datetime import datetime, date, timedelta
from http.server import ThreadingHTTPServer, BaseHTTPRequestHandler

# ---------------------------------------------------------------------------
# BLAKE3 (unkeyed, 32-byte output). This is a small original implementation
# sufficient for content-addressing cards without external dependencies.
# ---------------------------------------------------------------------------
IV = [
    0x6A09E667, 0xBB67AE85, 0x3C6EF372, 0xA54FF53A,
    0x510E527F, 0x9B05688C, 0x1F83D9AB, 0x5BE0CD19,
]
MSG_PERM = [2, 6, 3, 10, 7, 0, 4, 13, 1, 11, 12, 5, 9, 14, 15, 8]
MASK32 = 0xFFFFFFFF
CHUNK_LEN = 1024
BLOCK_LEN = 64
CHUNK_START = 1
CHUNK_END = 2
PARENT = 4
ROOT = 8


def _rotr32(x, n):
    return ((x >> n) | ((x << (32 - n)) & MASK32)) & MASK32


def _g(state, a, b, c, d, mx, my):
    state[a] = (state[a] + state[b] + mx) & MASK32
    state[d] = _rotr32(state[d] ^ state[a], 16)
    state[c] = (state[c] + state[d]) & MASK32
    state[b] = _rotr32(state[b] ^ state[c], 12)
    state[a] = (state[a] + state[b] + my) & MASK32
    state[d] = _rotr32(state[d] ^ state[a], 8)
    state[c] = (state[c] + state[d]) & MASK32
    state[b] = _rotr32(state[b] ^ state[c], 7)


def _compress(cv, block_words, counter, block_len, flags):
    state = cv[:] + IV[:4] + [counter & MASK32, (counter >> 32) & MASK32, block_len, flags]
    m = block_words[:]
    for _ in range(7):
        _g(state, 0, 4, 8, 12, m[0], m[1])
        _g(state, 1, 5, 9, 13, m[2], m[3])
        _g(state, 2, 6, 10, 14, m[4], m[5])
        _g(state, 3, 7, 11, 15, m[6], m[7])
        _g(state, 0, 5, 10, 15, m[8], m[9])
        _g(state, 1, 6, 11, 12, m[10], m[11])
        _g(state, 2, 7, 8, 13, m[12], m[13])
        _g(state, 3, 4, 9, 14, m[14], m[15])
        m = [m[i] for i in MSG_PERM]
    out = [0] * 16
    for i in range(8):
        out[i] = state[i] ^ state[i + 8]
        out[i + 8] = state[i + 8] ^ cv[i]
    return out


def _block_words(block):
    return list(struct.unpack('<16I', block + b'\0' * (64 - len(block))))


def _words_to_bytes(words):
    return b''.join(struct.pack('<I', w & MASK32) for w in words)


def _chunk_output(data, chunk_counter):
    cv = IV[:]
    off = 0
    first = True
    # Compress all but the last block as chaining-value blocks.
    while len(data) - off > BLOCK_LEN:
        flags = CHUNK_START if first else 0
        cv = _compress(cv, _block_words(data[off:off + BLOCK_LEN]), chunk_counter, BLOCK_LEN, flags)[:8]
        off += BLOCK_LEN
        first = False
    flags = (CHUNK_START if first else 0) | CHUNK_END
    block = data[off:]
    return (cv, _block_words(block), chunk_counter, len(block), flags)


def _output_bytes(output, root=False):
    cv, block_words, counter, block_len, flags = output
    if root:
        flags |= ROOT
    words = _compress(cv, block_words, counter, block_len, flags)
    return _words_to_bytes(words)


def _output_cv(output):
    cv, block_words, counter, block_len, flags = output
    return _compress(cv, block_words, counter, block_len, flags)[:8]


def _parent_output(left_cv, right_cv):
    block = _words_to_bytes(left_cv + right_cv)
    return (IV[:], _block_words(block), 0, BLOCK_LEN, PARENT)


def _parent_cv(left_cv, right_cv):
    return _output_cv(_parent_output(left_cv, right_cv))


def blake3_hex(data: bytes) -> str:
    if len(data) <= CHUNK_LEN:
        return _output_bytes(_chunk_output(data, 0), root=True)[:32].hex()
    cvs = []
    num_chunks = (len(data) + CHUNK_LEN - 1) // CHUNK_LEN
    for idx in range(num_chunks):
        chunk = data[idx * CHUNK_LEN:(idx + 1) * CHUNK_LEN]
        cv = _output_cv(_chunk_output(chunk, idx))
        total = idx + 1
        while total & 1 == 0:
            left = cvs.pop()
            cv = _parent_cv(left, cv)
            total >>= 1
        cvs.append(cv)
    cv = cvs.pop()
    while cvs:
        left = cvs.pop()
        # The last merge is emitted as the root output.
        if not cvs:
            return _output_bytes(_parent_output(left, cv), root=True)[:32].hex()
        cv = _parent_cv(left, cv)
    return _words_to_bytes(cv)[:32].hex()


# ---------------------------------------------------------------------------
# Card model / parser
# ---------------------------------------------------------------------------
class ParseError(Exception):
    def __init__(self, message, path, line):
        super().__init__(message)
        self.message = message
        self.path = str(path)
        self.line = line


class Card:
    def __init__(self, hash_, family_hash, deck_name, file_path, line_start, line_end, kind, data):
        self.hash = hash_
        self.family_hash = family_hash
        self.deck_name = deck_name
        self.file_path = str(file_path)
        self.line_start = int(line_start)
        self.line_end = int(line_end)
        self.kind = kind
        self.data = data

    def to_json_obj(self, performance):
        obj = {
            "hash": self.hash,
            "familyHash": self.family_hash,
            "deckName": self.deck_name,
            "location": {
                "filePath": self.file_path,
                "lineStart": self.line_start,
                "lineEnd": self.line_end,
            },
            "content": {},
            "performance": performance,
        }
        if self.kind == "basic":
            obj["content"]["basic"] = {
                "question": self.data["question"],
                "answer": self.data["answer"],
            }
        else:
            obj["content"]["cloze"] = {
                "text": self.data["text"],
                "start": self.data["start"],
                "end": self.data["end"],
            }
        return obj


def hash_basic(question, answer):
    return blake3_hex(("Basic" + question + answer).encode('utf-8'))


def hash_cloze_family(text):
    return blake3_hex(("Cloze" + text).encode('utf-8'))


def hash_cloze(text, start, end):
    end_u = end & 0xFFFFFFFFFFFFFFFF
    return blake3_hex(("Cloze" + text).encode('utf-8') + struct.pack('<Q', start) + struct.pack('<Q', end_u))


def normalize_block(lines):
    return "\n".join(lines).strip()


def is_q(line): return line.startswith("Q:")
def is_a(line): return line.startswith("A:")
def is_c(line): return line.startswith("C:")


def parse_cloze_deletions(raw):
    out = []
    spans = []
    in_cloze = False
    start = 0
    byte_pos = 0
    i = 0
    while i < len(raw):
        ch = raw[i]
        # Backslash escapes square brackets for cloze parsing, and the
        # backslash itself is removed, as observed in the web/export text.
        if ch == '\\' and i + 1 < len(raw) and raw[i + 1] in '[]':
            lit = raw[i + 1]
            out.append(lit)
            byte_pos += len(lit.encode('utf-8'))
            i += 2
            continue
        if ch == '[':
            in_cloze = True
            start = byte_pos
            i += 1
            continue
        if ch == ']':
            if in_cloze:
                end = byte_pos - 1
                if end < 0:
                    end = 0xFFFFFFFFFFFFFFFF
                spans.append((start, end))
                in_cloze = False
            i += 1
            continue
        out.append(ch)
        byte_pos += len(ch.encode('utf-8'))
        i += 1
    return "".join(out), spans


def parse_file(path: Path):
    abs_path = path.resolve()
    deck_name = path.stem
    try:
        text = abs_path.read_text(encoding='utf-8')
    except UnicodeDecodeError as e:
        raise e
    # Like Rust str::lines for normal files, but preserving trailing empty
    # lines so locations include them. split('\n') leaves a final empty item
    # for a single trailing newline; Rust lines() does not. The observed line
    # counts behave like splitlines() for one trailing newline and retain extra
    # blank lines; this adjustment matches that behavior.
    lines = text.split('\n')
    if lines and lines[-1] == '':
        lines.pop()
    cards = []
    state = None
    start_line = None
    q_lines = []
    a_lines = []
    c_lines = []

    def finish_basic(end_line):
        q = normalize_block(q_lines)
        a = normalize_block(a_lines)
        h = hash_basic(q, a)
        cards.append(Card(h, None, deck_name, abs_path, start_line, end_line, "basic", {"question": q, "answer": a}))

    def finish_cloze(end_line):
        raw = normalize_block(c_lines)
        cloze_text, spans = parse_cloze_deletions(raw)
        if not spans:
            raise ParseError("Cloze card must contain at least one cloze deletion", abs_path, start_line + 1)
        fam = hash_cloze_family(cloze_text)
        for st, en in spans:
            h = hash_cloze(cloze_text, st, en)
            cards.append(Card(h, fam, deck_name, abs_path, start_line, end_line, "cloze", {"text": cloze_text, "start": st, "end": en}))

    i = 0
    while i < len(lines):
        line = lines[i]
        if state is None:
            if is_q(line):
                state = 'q'
                start_line = i
                q_lines = [line[2:].strip()]
            elif is_a(line):
                raise ParseError("Found answer tag without a question", abs_path, i + 1)
            elif is_c(line):
                state = 'c'
                start_line = i
                c_lines = [line[2:].strip()]
            # other text outside cards is ignored
        elif state == 'q':
            if is_q(line):
                raise ParseError("New question without answer", abs_path, i + 1)
            elif is_a(line):
                state = 'a'
                a_lines = [line[2:].strip()]
            elif is_c(line):
                raise ParseError("Found cloze tag while reading a question", abs_path, i + 1)
            else:
                q_lines.append(line)
        elif state == 'a':
            if is_a(line):
                raise ParseError("Found answer tag while reading an answer", abs_path, i + 1)
            elif is_q(line):
                finish_basic(i)
                state = 'q'
                start_line = i
                q_lines = [line[2:].strip()]
                a_lines = []
            elif is_c(line):
                finish_basic(i)
                state = 'c'
                start_line = i
                c_lines = [line[2:].strip()]
                q_lines = []
                a_lines = []
            else:
                a_lines.append(line)
        elif state == 'c':
            if is_a(line):
                raise ParseError("Found answer tag while reading a cloze card", abs_path, i + 1)
            elif is_q(line):
                finish_cloze(i)
                state = 'q'
                start_line = i
                q_lines = [line[2:].strip()]
                c_lines = []
            elif is_c(line):
                finish_cloze(i)
                state = 'c'
                start_line = i
                c_lines = [line[2:].strip()]
            else:
                c_lines.append(line)
        i += 1

    if state == 'q':
        raise ParseError("File ended while reading a question without an answer", abs_path, start_line + 1)
    elif state == 'a':
        end_line = len(lines) - 1 if lines else 0
        finish_basic(end_line)
    elif state == 'c':
        end_line = len(lines) - 1 if lines else 0
        finish_cloze(end_line)
    return cards


def iter_markdown_files(root: Path):
    files = []
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames.sort()
        for fn in sorted(filenames):
            if fn.endswith('.md'):
                files.append(Path(dirpath) / fn)
    return files


def parse_collection(root: Path):
    all_cards = []
    seen = set()
    for path in iter_markdown_files(root):
        for card in parse_file(path):
            if card.hash not in seen:
                all_cards.append(card)
                seen.add(card.hash)
    all_cards.sort(key=lambda c: c.hash)
    return all_cards


def load_macros(root: Path):
    p = root / 'macros.tex'
    macros = []
    if not p.exists():
        return macros
    try:
        for line in p.read_text(encoding='utf-8').splitlines():
            stripped = line.strip()
            if not stripped:
                continue
            parts = stripped.split(None, 1)
            if len(parts) == 2:
                macros.append((parts[0], parts[1]))
    except OSError:
        pass
    return macros


# ---------------------------------------------------------------------------
# SQLite persistence
# ---------------------------------------------------------------------------
def ensure_collection_path(path: Path):
    if not path.exists():
        print("hashcards: error: directory does not exist.", file=sys.stderr)
        sys.exit(1)
    return path.resolve()


def connect_db(root: Path):
    db_path = root / 'hashcards.db'
    try:
        conn = sqlite3.connect(str(db_path))
    except sqlite3.Error as e:
        print(f"hashcards: error: {e}", file=sys.stderr)
        sys.exit(1)
    conn.row_factory = sqlite3.Row
    conn.executescript('''
        CREATE TABLE IF NOT EXISTS cards (
            hash TEXT PRIMARY KEY,
            last_reviewed_at TEXT,
            stability REAL,
            difficulty REAL,
            interval_raw REAL,
            interval_days INTEGER,
            due_date TEXT,
            review_count INTEGER
        );
        CREATE TABLE IF NOT EXISTS sessions (
            session_id INTEGER PRIMARY KEY AUTOINCREMENT,
            started_at TEXT NOT NULL,
            ended_at TEXT NOT NULL
        );
        CREATE TABLE IF NOT EXISTS reviews (
            review_id INTEGER PRIMARY KEY AUTOINCREMENT,
            session_id INTEGER NOT NULL,
            hash TEXT NOT NULL,
            reviewed_at TEXT NOT NULL,
            grade TEXT NOT NULL,
            stability REAL,
            difficulty REAL,
            interval_raw REAL,
            interval_days INTEGER,
            due_date TEXT
        );
    ''')
    conn.commit()
    return conn


def perf_for_hash(conn, h):
    row = conn.execute('SELECT * FROM cards WHERE hash=?', (h,)).fetchone()
    if not row:
        return None
    return {
        "lastReviewedAt": row['last_reviewed_at'],
        "stability": row['stability'],
        "difficulty": row['difficulty'],
        "intervalRaw": row['interval_raw'],
        "intervalDays": row['interval_days'],
        "dueDate": row['due_date'],
        "reviewCount": row['review_count'],
    }


def sessions_json(conn):
    sessions = []
    for s in conn.execute('SELECT * FROM sessions ORDER BY session_id'):
        reviews = []
        for r in conn.execute('SELECT * FROM reviews WHERE session_id=? ORDER BY review_id', (s['session_id'],)):
            reviews.append({
                "reviewId": r['review_id'],
                "hash": r['hash'],
                "reviewedAt": r['reviewed_at'],
                "grade": r['grade'],
                "stability": r['stability'],
                "difficulty": r['difficulty'],
                "intervalRaw": r['interval_raw'],
                "intervalDays": r['interval_days'],
                "dueDate": r['due_date'],
            })
        sessions.append({
            "sessionId": s['session_id'],
            "startedAt": s['started_at'],
            "endedAt": s['ended_at'],
            "reviews": reviews,
        })
    return sessions


# ---------------------------------------------------------------------------
# FSRS-like scheduling (matches observed first-review values)
# ---------------------------------------------------------------------------
STABILITY0 = {
    'Forgot': 0.40255,
    'Hard': 1.18385,
    'Good': 3.173,
    'Easy': 15.69105,
}
GRADE_NUM = {'Forgot': 1, 'Hard': 2, 'Good': 3, 'Easy': 4}
W4 = 7.1949
W5 = 0.5345


def schedule_review(conn, h, grade, reviewed_at_dt):
    prev = conn.execute('SELECT * FROM cards WHERE hash=?', (h,)).fetchone()
    g = GRADE_NUM[grade]
    if prev is None:
        stability = STABILITY0[grade]
        difficulty = W4 - math.exp((g - 1) * W5) + 1
        review_count = 1
    else:
        # A compact approximation for later reviews: keep behavior stable and
        # monotonic without depending on external FSRS libraries.
        old_s = float(prev['stability'])
        old_d = float(prev['difficulty'])
        if grade == 'Forgot':
            stability = max(0.1, old_s * 0.45)
            difficulty = min(10.0, old_d + 1.2)
        elif grade == 'Hard':
            stability = max(1.0, old_s * 1.2)
            difficulty = min(10.0, old_d + 0.4)
        elif grade == 'Good':
            stability = old_s * 2.5
            difficulty = max(1.0, old_d - 0.15)
        else:
            stability = old_s * 3.8
            difficulty = max(1.0, old_d - 0.6)
        review_count = int(prev['review_count']) + 1
    # The original computes an interval formula that is mathematically the
    # stability at 90% retention, yielding the following floating artifacts.
    interval_raw = stability * 0.9999999999999998
    interval_days = int(round(interval_raw))
    if interval_days < 1:
        interval_days = 1
    due = (reviewed_at_dt.date() + timedelta(days=interval_days)).isoformat()
    reviewed_at = fmt_ts(reviewed_at_dt)
    conn.execute('''INSERT INTO cards(hash,last_reviewed_at,stability,difficulty,interval_raw,interval_days,due_date,review_count)
                    VALUES(?,?,?,?,?,?,?,?)
                    ON CONFLICT(hash) DO UPDATE SET
                      last_reviewed_at=excluded.last_reviewed_at,
                      stability=excluded.stability,
                      difficulty=excluded.difficulty,
                      interval_raw=excluded.interval_raw,
                      interval_days=excluded.interval_days,
                      due_date=excluded.due_date,
                      review_count=excluded.review_count''',
                 (h, reviewed_at, stability, difficulty, interval_raw, interval_days, due, review_count))
    return {
        'hash': h,
        'reviewed_at': reviewed_at,
        'grade': grade,
        'stability': stability,
        'difficulty': difficulty,
        'interval_raw': interval_raw,
        'interval_days': interval_days,
        'due_date': due,
    }


def fmt_ts(dt=None):
    if dt is None:
        dt = datetime.now()
    return dt.strftime('%Y-%m-%dT%H:%M:%S.%f')[:-3]


def parse_ts(ts):
    try:
        return datetime.strptime(ts, '%Y-%m-%dT%H:%M:%S.%f')
    except Exception:
        return datetime.now()


