def dump_json(obj, trailing_newline=True):
    s = json.dumps(obj, ensure_ascii=False, indent=2)
    if trailing_newline:
        print(s)
    else:
        sys.stdout.write(s)
    return s


def cmd_check(root):
    root = ensure_collection_path(root)
    conn = connect_db(root)
    conn.close()
    parse_collection(root)
    print('ok')


def export_obj(root, conn):
    cards = parse_collection(root)
    return {
        "cards": [c.to_json_obj(perf_for_hash(conn, c.hash)) for c in cards],
        "sessions": sessions_json(conn),
    }


def cmd_export(root, output=None):
    root = ensure_collection_path(root)
    conn = connect_db(root)
    obj = export_obj(root, conn)
    conn.close()
    s = json.dumps(obj, ensure_ascii=False, indent=2)
    if output:
        try:
            Path(output).write_text(s, encoding='utf-8')
        except OSError as e:
            print('hashcards: error: I/O error: Os {', file=sys.stderr)
            print(f'    code: {e.errno},', file=sys.stderr)
            # Python names differ slightly from Rust; use common display.
            kind = 'NotFound' if e.errno == 2 else e.__class__.__name__
            print(f'    kind: {kind},', file=sys.stderr)
            print(f'    message: "{e.strerror}",', file=sys.stderr)
            print('}', file=sys.stderr)
            sys.exit(1)
    else:
        print(s)


def cmd_stats(root, fmt):
    root = ensure_collection_path(root)
    conn = connect_db(root)
    cards = parse_collection(root)
    if fmt == 'html':
        print('HTML output is not implemented yet.', file=sys.stderr)
        conn.close()
        return
    today = date.today().isoformat()
    cards_db = conn.execute('SELECT COUNT(*) FROM cards').fetchone()[0]
    reviewed_today = conn.execute('SELECT COUNT(*) FROM reviews WHERE substr(reviewed_at,1,10)=?', (today,)).fetchone()[0]
    obj = {
        "cardsInDeckCount": len(cards),
        "cardsInDbCount": cards_db,
        "texMacroCount": len(load_macros(root)),
        "cardsReviewedTodayCount": reviewed_today,
    }
    conn.close()
    dump_json(obj)


def orphan_hashes(root, conn):
    deck_hashes = {c.hash for c in parse_collection(root)}
    db_hashes = [r[0] for r in conn.execute('SELECT hash FROM cards ORDER BY hash')]
    return [h for h in db_hashes if h not in deck_hashes]


def cmd_orphans(root, delete=False):
    root = ensure_collection_path(root)
    conn = connect_db(root)
    hashes = orphan_hashes(root, conn)
    for h in hashes:
        print(h)
    if delete and hashes:
        for h in hashes:
            conn.execute('DELETE FROM cards WHERE hash=?', (h,))
            conn.execute('DELETE FROM reviews WHERE hash=?', (h,))
        conn.commit()
    conn.close()


