def render_inline(text, base_url):
    # Escape first, then restore simple Markdown inline constructs.
    out = []
    i = 0
    while i < len(text):
        if text.startswith('`', i):
            j = text.find('`', i + 1)
            if j != -1:
                out.append('<code>' + html.escape(text[i + 1:j]) + '</code>')
                i = j + 1
                continue
        if text.startswith('$', i):
            # display $$ handled at block level; here do inline math
            if i + 1 < len(text) and text[i + 1] == '$':
                out.append(html.escape(text[i]))
                i += 1
                continue
            j = text.find('$', i + 1)
            if j != -1:
                out.append('<span class="math math-inline">' + html.escape(text[i + 1:j]) + '</span>')
                i = j + 1
                continue
        # simple emphasis _x_
        if text.startswith('_', i):
            j = text.find('_', i + 1)
            if j != -1:
                out.append('<em>' + html.escape(text[i + 1:j]) + '</em>')
                i = j + 1
                continue
        out.append(html.escape(text[i]))
        i += 1
    return ''.join(out)


def asset_url(src, base_url):
    if src.startswith('@/'):
        return base_url + '/file/' + urllib.parse.quote(src[2:])
    if '://' in src:
        return src
    return base_url + '/file/' + urllib.parse.quote(src)


def render_markdown(md, base_url):
    # A focused Markdown renderer for the constructs used by decks.
    if md == '':
        return ''
    lines = md.split('\n')
    blocks = []
    i = 0
    while i < len(lines):
        if lines[i].strip() == '':
            i += 1
            continue
        if lines[i].strip() == '$$':
            j = i + 1
            math_lines = []
            while j < len(lines) and lines[j].strip() != '$$':
                math_lines.append(lines[j])
                j += 1
            blocks.append('<p><span class="math math-display">\n' + html.escape('\n'.join(math_lines)) + '\n</span></p>')
            i = j + 1 if j < len(lines) else j
            continue
        if lines[i].lstrip().startswith('- '):
            items = []
            while i < len(lines) and lines[i].lstrip().startswith('- '):
                item = lines[i].lstrip()[2:]
                items.append('<li>' + render_inline(item, base_url) + '</li>')
                i += 1
            blocks.append('<ul>\n' + ''.join(items) + '\n</ul>')
            continue
        # paragraph until blank or special block
        para = []
        while i < len(lines) and lines[i].strip() != '' and not lines[i].lstrip().startswith('- ') and lines[i].strip() != '$$':
            para.append(lines[i])
            i += 1
        ptxt = '\n'.join(para)
        # image-only paragraph
        img_m = None
        import re
        img_m = re.fullmatch(r'!\[(.*?)\]\((.*?)\)', ptxt.strip())
        if img_m:
            alt = html.escape(img_m.group(1))
            src = html.escape(asset_url(img_m.group(2), base_url), quote=True)
            blocks.append(f'<p><img src="{src}" alt="{alt}" /></p>')
        else:
            blocks.append('<p>' + render_inline(ptxt, base_url).replace('\n', '\n') + '</p>')
    return '\n'.join(blocks) + ('\n' if blocks else '')


def render_cloze_prompt(text, start, end, revealed, base_url):
    b = text.encode('utf-8')
    if end == 0xFFFFFFFFFFFFFFFF:
        end_excl = start
    else:
        end_excl = end + 1
    before = b[:start].decode('utf-8', errors='ignore')
    hidden = b[start:end_excl].decode('utf-8', errors='ignore')
    after = b[end_excl:].decode('utf-8', errors='ignore')
    marker = '<span class=\'cloze-reveal\'>' + html.escape(hidden) + '</span>' if revealed else "<span class='cloze'>.............</span>"
    # Render surrounding markdown lightly by escaping and preserving paragraphs.
    combined = html.escape(before) + marker + html.escape(after)
    paras = combined.split('\n\n')
    return ''.join('<p>' + p.replace('\n', '\n') + '</p>\n' for p in paras)


