def die_clap(msg, usage=None, tip=None):
    print(msg, file=sys.stderr)
    if tip:
        print('', file=sys.stderr); print(tip, file=sys.stderr)
    if usage:
        print('', file=sys.stderr); print(usage, file=sys.stderr)
    print('', file=sys.stderr); print("For more information, try '--help'.", file=sys.stderr)
    sys.exit(2)


def parse_dir(args):
    if not args:
        return Path('.')
    if len(args) == 1:
        return Path(args[0])
    die_clap(f"error: unexpected argument '{args[1]}' found")


def parse_int_value(opt, val):
    try:
        n = int(val)
        if n < 0:
            raise ValueError
        return n
    except Exception:
        die_clap(f"error: invalid value '{val}' for '{opt} <{opt[2:].replace('-', '_').upper()}>'")


def parse_bool_option(name, val):
    if val == 'true': return True
    if val == 'false': return False
    die_clap(f"error: invalid value '{val}' for '{name} <{name[2:].replace('-', '_').upper()}>'\n  [possible values: true, false]")


def handle_parse_error(e):
    print(f"hashcards: error: Parse error: {e.message}. Location: {e.path}:{e.line}", file=sys.stderr)
    sys.exit(1)


def main(argv):
    if not argv or argv[0] in ('-h', '--help'):
        print(MAIN_HELP)
        return
    if argv[0] in ('-V', '--version'):
        print('hashcards 0.3.0')
        return
    if argv[0] == 'help':
        rest = argv[1:]
        if not rest:
            print(MAIN_HELP); return
        if rest[0] == 'drill': print(DRILL_HELP_LONG); return
        if rest[0] == 'check': print(CHECK_HELP); return
        if rest[0] == 'stats': print(STATS_HELP_LONG); return
        if rest[0] == 'export': print(EXPORT_HELP); return
        if rest[0] == 'orphans':
            if len(rest) >= 2 and rest[1] == 'list': print(ORPHANS_LIST_HELP); return
            if len(rest) >= 2 and rest[1] == 'delete': print(ORPHANS_DELETE_HELP); return
            print(ORPHANS_HELP); return
        die_clap(f"error: unrecognized subcommand '{rest[0]}'", "Usage: executable <COMMAND>")
    cmd = argv[0]
    args = argv[1:]
    try:
        if cmd == 'check':
            if args and args[0] in ('-h', '--help'):
                print(CHECK_HELP); return
            cmd_check(parse_dir(args))
        elif cmd == 'stats':
            if args and args[0] == '--help': print(STATS_HELP_LONG); return
            if args and args[0] == '-h': print(STATS_HELP_SHORT); return
            fmt = 'html'; rest = []
            i = 0
            while i < len(args):
                a = args[i]
                if a == '--format':
                    if i + 1 >= len(args): die_clap("error: a value is required for '--format <FORMAT>'")
                    fmt = args[i + 1]; i += 2; continue
                if a.startswith('--format='):
                    fmt = a.split('=', 1)[1]; i += 1; continue
                if a.startswith('--'):
                    die_clap(f"error: unexpected argument '{a}' found", "Usage: executable stats [OPTIONS] [DIRECTORY]", f"  tip: to pass '{a}' as a value, use '-- {a}'")
                rest.append(a); i += 1
            if fmt not in ('html', 'json'):
                tip = "  tip: a similar value exists: 'html'" if fmt == 'xml' else None
                msg = f"error: invalid value '{fmt}' for '--format <FORMAT>'\n  [possible values: html, json]"
                die_clap(msg, None, tip)
            cmd_stats(parse_dir(rest), fmt)
        elif cmd == 'export':
            if args and args[0] in ('-h', '--help'):
                print(EXPORT_HELP); return
            output = None; rest = []
            i = 0
            while i < len(args):
                a = args[i]
                if a == '--output':
                    if i + 1 >= len(args): die_clap("error: a value is required for '--output <OUTPUT>'")
                    output = args[i + 1]; i += 2; continue
                if a.startswith('--output='):
                    output = a.split('=', 1)[1]; i += 1; continue
                if a.startswith('--'):
                    die_clap(f"error: unexpected argument '{a}' found", "Usage: executable export [OPTIONS] [DIRECTORY]")
                rest.append(a); i += 1
            cmd_export(parse_dir(rest), output)
        elif cmd == 'orphans':
            if not args:
                print(ORPHANS_HELP, file=sys.stderr); sys.exit(2)
            if args[0] in ('-h', '--help'):
                print(ORPHANS_HELP); return
            sub = args[0]
            if sub == 'help':
                if len(args) > 1 and args[1] == 'list': print(ORPHANS_LIST_HELP)
                elif len(args) > 1 and args[1] == 'delete': print(ORPHANS_DELETE_HELP)
                else: print(ORPHANS_HELP)
                return
            if sub == 'list':
                if len(args) > 1 and args[1] in ('-h', '--help'):
                    print(ORPHANS_LIST_HELP); return
                cmd_orphans(parse_dir(args[1:]), delete=False)
            elif sub == 'delete':
                if len(args) > 1 and args[1] in ('-h', '--help'):
                    print(ORPHANS_DELETE_HELP); return
                cmd_orphans(parse_dir(args[1:]), delete=True)
            else:
                die_clap(f"error: unrecognized subcommand '{sub}'", "Usage: executable orphans <COMMAND>")
        elif cmd == 'drill':
            if args and args[0] == '--help': print(DRILL_HELP_LONG); return
            if args and args[0] == '-h': print(DRILL_HELP_SHORT); return
            opts = {'host': '127.0.0.1', 'port': 8000, 'answer_controls': 'full', 'bury_siblings': True}
            rest = []
            i = 0
            while i < len(args):
                a = args[i]
                def need():
                    if i + 1 >= len(args): die_clap(f"error: a value is required for '{a} <VALUE>'")
                    return args[i + 1]
                if a == '--card-limit': opts['card_limit'] = parse_int_value(a, need()); i += 2; continue
                if a.startswith('--card-limit='): opts['card_limit'] = parse_int_value('--card-limit', a.split('=',1)[1]); i += 1; continue
                if a == '--new-card-limit': opts['new_card_limit'] = parse_int_value(a, need()); i += 2; continue
                if a.startswith('--new-card-limit='): opts['new_card_limit'] = parse_int_value('--new-card-limit', a.split('=',1)[1]); i += 1; continue
                if a == '--host': opts['host'] = need(); i += 2; continue
                if a.startswith('--host='): opts['host'] = a.split('=',1)[1]; i += 1; continue
                if a == '--port': opts['port'] = parse_int_value(a, need()); i += 2; continue
                if a.startswith('--port='): opts['port'] = parse_int_value('--port', a.split('=',1)[1]); i += 1; continue
                if a == '--from-deck': opts['from_deck'] = need(); i += 2; continue
                if a.startswith('--from-deck='): opts['from_deck'] = a.split('=',1)[1]; i += 1; continue
                if a == '--open-browser': parse_bool_option(a, need()); i += 2; continue
                if a.startswith('--open-browser='): parse_bool_option('--open-browser', a.split('=',1)[1]); i += 1; continue
                if a == '--bury-siblings': opts['bury_siblings'] = parse_bool_option(a, need()); i += 2; continue
                if a.startswith('--bury-siblings='): opts['bury_siblings'] = parse_bool_option('--bury-siblings', a.split('=',1)[1]); i += 1; continue
                if a == '--answer-controls':
                    val = need()
                    if val not in ('full', 'binary'):
                        die_clap(f"error: invalid value '{val}' for '--answer-controls <ANSWER_CONTROLS>'\n  [possible values: full, binary]")
                    opts['answer_controls'] = val; i += 2; continue
                if a.startswith('--answer-controls='):
                    val = a.split('=',1)[1]
                    if val not in ('full','binary'):
                        die_clap(f"error: invalid value '{val}' for '--answer-controls <ANSWER_CONTROLS>'\n  [possible values: full, binary]")
                    opts['answer_controls'] = val; i += 1; continue
                if a.startswith('--'):
                    die_clap(f"error: unexpected argument '{a}' found", "Usage: executable drill [OPTIONS] [DIRECTORY]")
                rest.append(a); i += 1
            cmd_drill(parse_dir(rest), opts)
        else:
            die_clap(f"error: unrecognized subcommand '{cmd}'", "Usage: executable <COMMAND>")
    except ParseError as e:
        handle_parse_error(e)
    except BrokenPipeError:
        pass


